const outcome = (post, r, photos, note) => {
  const stamp = DateTime.now().setZone(TZ).toISO({ suppressMilliseconds: true });
  if (r.id) {
    const [pageId, postId] = String(r.id).split('_');
    return { Id: post.Id, ok: true, status: 'published', fb_post_id: r.id, published_at: stamp, final_text: post.message, check_report: post.check_report, format: photos > 1 ? 'photos' : photos === 1 ? 'photo' : 'text', note, link: `https://www.facebook.com/${pageId}/posts/${postId}`, title: post.title };
  }
  const reason = (r.error && (r.error.message || JSON.stringify(r.error))) || 'no post id returned';
  return { Id: post.Id, ok: false, status: 'publish_failed', fb_post_id: null, published_at: null, final_text: post.final || null, format: null, check_report: `Facebook refused it: ${reason}${note ? ` (${note})` : ''}`, note, title: post.title };
};

const posts = $('With pictures?').all(1).map((i) => i.json);
return $input.all().map((item, i) => ({ json: outcome(posts[i], item.json || {}, 0, '') }));

const token = $json.tenant_access_token;
if (!token) throw new Error('No Lark tenant token: ' + JSON.stringify($json).slice(0, 300));
return $('Picture list').all().map((i) => ({ json: { ...i.json, auth: token } }));

// Posts go out even when pictures fail: the text is written to stand alone.
const post = $('Each picture post').first().json;
const uploads = $input.all().map((i) => i.json || {});
const ids = uploads.filter((u) => u.id).map((u) => u.id);
const errors = uploads.filter((u) => !u.id).map((u) => (u.error && (u.error.message || JSON.stringify(u.error))) || 'upload failed');
const body = ids.length ? { message: post.message, attached_media: ids.map((id) => ({ media_fbid: id })) } : { message: post.message };
return [{ json: { body, photos: ids.length, note: errors.length ? `${errors.length} of ${uploads.length} picture(s) failed: ${[...new Set(errors)].join('; ')}` : '' } }];

